const base_url = ''
const output_dir = 'app'
const user_agent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
const max_concurrent = 50
const connection_timeout = 10 * time.second

struct Stats {
mut:
  pages_crawled      u64
  pages_saved        u64
  errors             u64
  duplicates_skipped u64
  bytes_downloaded   u64
  start_time         i64
  end_time           i64
}

struct Crawler {
  base_url       string
  domain         string
  output_dir     string
  manifest_path  string
  metadata_path  string
  client         http.Client
mut:
  stats          Stats
  visited        map[string]bool
  visited_mutex  sync.Mutex
  file_mutex     sync.Mutex
  active_workers sync.WaitGroup
  work_queue     chan string
  processing     sync.WaitGroup
}

fn new_crawler() &Crawler {
  parsed := urllib.parse(base_url) or { panic(err) }
  host := parsed.host
  wd := os.getwd()
  out := os.join_path(wd, output_dir)
  if !os.is_dir(out) {
    os.mkdir_all(out) or { panic(err) }
  }
  return &Crawler{
    base_url: base_url
    domain: host
    output_dir: out
    manifest_path: os.join_path(out, 'manifest.txt')
    metadata_path: os.join_path(out, 'metadata.json')
    client: http.Client{
      read_timeout: connection_timeout
      write_timeout: connection_timeout
    }
    visited: map[string]bool{}
    work_queue: chan string{cap: 10000}
  }
}

fn (mut c Crawler) is_visited(url string) bool {
  c.visited_mutex.lock()
  defer { c.visited_mutex.unlock() }
  if url in c.visited {
    return true
  }
  c.visited[url] = true
  return false
}

fn sanitize_filename(url string) string {
  hash := sha256.sum(url.bytes())
  return hex.encode(hash[..]) + '.txt'
}

fn (mut c Crawler) save_content(url string, content string) {
  filename := sanitize_filename(url)
  path := os.join_path(c.output_dir, filename)
  os.write_file(path, content) or {
    c.stats.errors++
    return
  }
  content_hash_bytes := sha256.sum(content.bytes())
  content_hash := hex.encode(content_hash_bytes[..])
  line := '${filename}\t${url}\t${content_hash}\n'
  c.file_mutex.lock()
  mut f := os.open_append(c.manifest_path) or {
    c.file_mutex.unlock()
    return
  }
  f.write_string(line) or {}
  f.close()
  c.file_mutex.unlock()
  c.stats.pages_saved++
}

fn extract_links(html string, base_url string, domain string) []string {
  mut links := []string{}
  mut idx := 0
  for {
    start_href := html.index_after('href="', idx)
    if start_href == -1 {
      break
    }
    start_quote := start_href + 6
    end_quote := html.index_after('"', start_quote)
    if end_quote == -1 {
      break
    }
    raw_url := html[start_quote..end_quote]
    idx = end_quote
    if raw_url.len < 1 || raw_url.starts_with('#') || raw_url.starts_with('mailto:') || raw_url.starts_with('javascript:') {
      continue
    }
    mut absolute_url := raw_url
    if !raw_url.starts_with('http') {
      parsed_base := urllib.parse(base_url) or { continue }
      if raw_url.starts_with('/') {
        absolute_url = '${parsed_base.scheme}://${parsed_base.host}${raw_url}'
      } else {
        mut path := parsed_base.path
        if !path.ends_with('/') {
          last_slash := path.last_index('/') or { -1 }
          if last_slash != -1 {
            path = path[..last_slash + 1]
          } else {
            path = '/'
          }
        }
        absolute_url = '${parsed_base.scheme}://${parsed_base.host}${path}${raw_url}'
      }
    }
    parsed_link := urllib.parse(absolute_url) or { continue }
    if parsed_link.host != domain {
      continue
    }
    link_clean := absolute_url.split('#')[0]
    links << link_clean
  }
  return links
}

fn clean_html(html string) string {
  mut res := html.replace_each(['<script', '\x00<script', '</script>', '</script>\x00', '<style', '\x00<style', '</style>', '</style>\x00'])
  parts := res.split('\x00')
  mut sb := []string{}
  for part in parts {
    if part.starts_with('<script') || part.starts_with('<style') {
      continue
    }
    sb << part
  }
  text := sb.join(' ')
  mut in_tag := false
  mut clean := []u8{}
  for ch in text {
    if ch == `<` {
      in_tag = true
      continue
    }
    if ch == `>` {
      in_tag = false
      clean << ` `
      continue
    }
    if !in_tag {
      clean << ch
    }
  }
  final_str := clean.bytestr()
  mut lines := []string{}
  for line in final_str.split('\n') {
    trimmed := line.trim_space()
    if trimmed.len > 0 {
      lines << trimmed
    }
  }
  return lines.join('\n')
}

fn (mut c Crawler) fetch(url string) ?string {
  req := http.new_request(http.Method.get, url, '')
  req.header.add(.user_agent, user_agent)
  resp := c.client.do(req) or {
    c.stats.errors++
    return none
  }
  if resp.status_code != 200 {
    c.stats.errors++
    return none
  }
  ct := resp.header.get(.content_type) or { '' }
  if !ct.contains('text/html') {
    return none
  }
  c.stats.bytes_downloaded += u64(resp.body.len)
  return resp.body
}

fn (mut c Crawler) worker() {
  for {
    select {
      url := <-c.work_queue {
        if c.is_visited(url) {
          c.stats.duplicates_skipped++
          c.processing.done()
          continue
        }
        println('[Worker] Processing: ${url}')
        html := c.fetch(url) or {
          c.processing.done()
          continue
        }
        c.stats.pages_crawled++
        text := clean_html(html)
        if text.len > 0 {
          c.save_content(url, text)
        }
        links := extract_links(html, url, c.domain)
        for link in links {
          c.processing.add(1)
          c.work_queue <- link
        }
        c.processing.done()
      }
      1 * time.second {
        return
      }
    }
  }
  c.active_workers.done()
}

fn (mut c Crawler) run() {
  c.stats.start_time = time.now().unix()
  println('Starting crawl of ${c.base_url} with ${max_concurrent} workers...')
  if os.exists(c.manifest_path) {
    os.rm(c.manifest_path) or {}
  }
  c.processing.add(1)
  c.work_queue <- c.base_url
  for _ in 0 .. max_concurrent {
    c.active_workers.add(1)
    spawn c.worker()
  }
  c.processing.wait()
  c.stats.end_time = time.now().unix()
  c.save_metadata()
  duration := c.stats.end_time - c.stats.start_time
  println('=================================================')
  println('Crawl Complete.')
  println('Duration: ${duration}s')
  println('Pages Crawled: ${c.stats.pages_crawled}')
  println('Pages Saved: ${c.stats.pages_saved}')
  println('Errors: ${c.stats.errors}')
  println('Data: ${c.stats.bytes_downloaded / 1024} KB')
}

fn (mut c Crawler) save_metadata() {
  json := '{
  "domain": "${c.domain}",
  "base_url": "${c.base_url}",
  "stats": {
    "crawled": ${c.stats.pages_crawled},
    "saved": ${c.stats.pages_saved},
    "errors": ${c.stats.errors},
    "duration_sec": ${c.stats.end_time - c.stats.start_time}
  }
}'
  os.write_file(c.metadata_path, json) or {}
}

fn main() {
  mut crawler := new_crawler()
  crawler.run()
}


